        ALTER TABLE commerce.commerce_products ADD CONSTRAINT commerce_products_item_fk
            FOREIGN KEY (org_id, item_id) REFERENCES commerce.itm_items (org_id, id) ON DELETE RESTRICT;
    END IF;
END
$erp_item_fk$;
